use vstd::prelude::*;

verus! {

    // Specification: number of adjacent equal‐char pairs in a sequence
    spec fn count_adj(s: Seq<char>) -> nat
        decreases s.len()
    {
        if s.len() <= 1 {
            0
        } else {
            let first  = s.index(0);
            let second = s.index(1);
            (if first == second { 1 } else { 0 })
                + count_adj(s.slice(1, s.len()))
        }
    }

    // solve: count how many k in [0 .. n-2] have s[k] == s[k+1]
    fn solve(n: i8, s: Vec<char>) -> i8
        requires n >= 1
        requires s.len() == (n as usize)
        ensures  result >= 0
        ensures  result <= n - 1
        ensures (result as nat) == count_adj(s.view())
    {
        let mut i: i8 = 0;
        let mut count: i8 = 0;

        // loop over indices i = 0 .. n-2
        while i < n - 1
            invariant 0 <= i && i <= n - 1
            invariant 0 <= count
            // Tie count to the spec on the prefix s[0..i+1]:
            invariant (count as nat)
                == count_adj(s.view().slice(0, (i as nat) + 1))
            decreases ((n - 1) - i) as nat
        {
            // check the pair at (i, i+1)
            if s[i as usize] == s[(i + 1) as usize] {
                count += 1;
            }
            i += 1;
        }

        // at the end i == n-1, so we've covered all k in [0..n-2]
        count
    }

} // end verus!

